    excerpt: "Die meisten BIM-Projekte liefern weiterhin IFC2x3, obwohl IFC4 seit 2018 der ISO-Standard ist. Was sich mit IFC4 ändert, wann sich ein Umstieg lohnt und wie Sie den Übergang meistern, ohne bestehende Tools zu brechen.",
