        text: "Der Datensatz FILE_NAME im STEP-Dateikopf der IFC-Datei enthält die Felder Autor und Organisation. ISO 19650-2 §9.1 verlangt, dass diese für die Nachvollziehbarkeit ausgefüllt werden. Die meisten Tools lassen sie standardmäßig als leere Zeichenketten stehen.",
