        text: "Verwenden Sie den Open-Source-IFC-Exporter und setzen Sie unter File → Export → IFC → Modify Setup → Advanced die Option „Export IFC GUIDs“ auf „Keep Existing“ (niemals „Generate New“). So wird die stabile GlobalId wiederverwendet, die Revit pro Element speichert, statt bei jedem Export eine neue zu erzeugen. Für Elemente, die in mehrere IFC-Entitäten aufgeteilt werden, akzeptieren Sie, dass die Unterentitäten möglicherweise nicht perfekt stabil sind – verankern Sie Ihre Koordination auf der ID des Host-Elements.",
