        type: "p",
        text: "Artikel 4 der DSGVO definiert personenbezogene Daten als alle Informationen, die sich auf eine identifizierte oder identifizierbare natürliche Person beziehen. Die meisten IFC-Dateien enthalten im offensichtlichen Sinne keine personenbezogenen Daten – sie beschreiben Gebäude, keine Personen. Doch Grenzfälle kommen häufiger vor, als viele Teams annehmen:",
