        text: "Das schwächste Glied in jedem Qualitätsprozess ist, dass Prüfung und Behauptung zwei getrennte Dinge sind. Jeder kann behaupten, ein Modell habe 92 Punkte erreicht. Ein Prüfnachweis bindet die Zahl an eine konkrete Datei: den Fingerabdruck der Datei selbst, den Regelsatz, das Schema, den Zeitstempel, den Score.",
