          "Er wird aus dem Inhalt der Datei abgeleitet, sodass erkennbar wird, wenn ein einziges Byte des Modells geändert und derselbe Nachweis erneut ausgestellt wird.",
          "Er ist vom Empfänger unabhängig überprüfbar, ohne Ihr Zutun. Ein Nachweis, den nur Ihre eigene Software bestätigen kann, ist ein Versprechen, kein Beweis.",
