        type: "callout",
        variant: "info",
        text: "Das gewinnt Jahr für Jahr an Bedeutung. Sobald eine Lieferung an einen Zahlungsmeilenstein geknüpft ist – und das ist zunehmend der Fall –, wird „wir haben geprüft“ von einer professionellen Höflichkeit zu einer Behauptung, die jemand anfechten kann. Der günstigste Moment, sie überprüfbar zu machen, ist, bevor sie angefochten wird.",
