        type: "p",
        text: "Nichts davon ist neue Technologie, und nichts davon erfordert ein Werkzeug, das Sie nicht bereits haben. Es erfordert, eine Lieferung als Behauptung zu behandeln, die jemand anderes überprüfen können muss – eine kleine Haltungsänderung mit unverhältnismäßig großer Wirkung darauf, wie oft Lieferungen zurückkommen.",
