        type: "p",
        text: "IDS validiert nur das, was die .ids-Spezifikation deklariert. Wenn Ihre Datei FireRating an Wänden verlangt, Ihre AIA aber auch IsExternal an Türen, Uniclass-Codes an Tragwerkselementen und Mengensätze an Decken vorschreibt – und diese nicht in die Spezifikation aufgenommen wurden –, meldet die Engine, alle Anforderungen seien erfüllt, während die Hälfte Ihrer AIA ungeprüft bleibt. Ein bestandener IDS-Check ist eine vertragliche Bestätigung gegen eine bestimmte Spezifikation. Er ist kein allgemeines Qualitätszertifikat.",
