        type: "p",
        text: "Ein verbreiteter Reflex ist es, die IFC zu öffnen, das 3D-Modell zu betrachten, und wenn das Gebäude richtig aussieht, die Datei für fertig zu erklären. Die Geometrie macht nur rund 30 % dessen aus, was eine IFC-Datei brauchbar macht. Eigenschaftssätze, Klassifizierungen, Elementnamen, Typzuweisungen und Mengensätze sind das, was FM-Systeme, Kostenmanager und CDE-Anlagenregister tatsächlich verwenden. Eine geometrisch korrekte Datei mit leeren Eigenschaftssätzen scheitert bei der Übergabe.",
