        text: "Wer die Validierung als letzten Schritt vor der CDE-Übergabe behandelt, muss Probleme unter Druck und ohne Puffer beheben. Ein Modell mit 800 am Tag vor dem Termin entdeckten Validierungsproblemen wird entweder mit bekannten Mängeln geliefert oder verpasst den Termin. Der richtige Rhythmus: Level 1 nach jedem Export, Level 2 vor jeder internen Prüfung (mindestens wöchentlich), Level 3 zwei Wochen vor jedem formalen Meilenstein.",
