        text: "Doppelte GUIDs innerhalb einer Datei sind ein Level-1-Problem und von jedem Validator erkennbar. Aber GUID-Instabilität über mehrere Re-Exporte hinweg – bei der dasselbe Element bei jedem Export des Modells eine andere GlobalId erhält – bleibt bei der Validierung einer einzelnen Datei unsichtbar. Wenn GlobalIds zwischen Revisionen driften, wird jeder BCF-Kommentar, jede CDE-Elementreferenz und jede FM-Anlagenkennung stillschweigend zu einer toten Referenz. Das erfordert einen Vergleich zweier Revisionen und eine Prüfung der Exporteinstellungen – nicht nur die Validierung einer einzelnen Datei.",
