          "Zwei Wochen vor jeder formalen Meilenstein-Lieferung: alle drei Ebenen ausführen. Ziel: Health Score ≥ 80 vor IDS. Zwei Wochen geben Zeit zur Nacharbeit ohne Druck. Frühzeitig melden – den Puffer nicht aufbrauchen.",
          "Vor dem Upload in die CDE: Level 2 und Level 3 ausführen. Das Health-Score-Zertifikat und den IDS-Prüfbericht dem Transmittal beifügen. Das schafft eine dokumentierte Nachweiskette und gibt dem Informationsmanager alles, was für die Annahme der Lieferung nötig ist.",
