        text: "Nein. Level 1 und Level 2 messen völlig unterschiedliche Eigenschaften einer Datei. Eine schemakonforme Datei (Level 1) kann null Eigenschaftssätze, leere Elementnamen, keine Klassifizierung und keine ISO-19650-Metadaten haben – und bei der Qualitätsprüfung (Level 2) trotzdem nur 20 Punkte erreichen. Sie brauchen immer beides. Level 1 heißt „die Datei ist korrekt verpackt“, Level 2 heißt „der Inhalt des Pakets entspricht dem Bestellten“.",
