        text: "Nein. IDS prüft projektspezifische Informationsanforderungen (Level 3). Der buildingSMART Validation Service prüft die Schemakonformität (Level 1). Beide arbeiten auf völlig unterschiedlichen Ebenen und beantworten unterschiedliche Fragen. Ein Modell, das IDS besteht, aber die Schema-Validierung nicht besteht, wäre ein logischer Widerspruch – die Integrität nach Level 1 ist Voraussetzung für eine aussagekräftige Prüfung nach Level 3.",
