        text: "Bei Architektur A wird die IFC-Datei von einer Infrastruktur verarbeitet, die Sie nicht kontrollieren. Sie durchquert ein Netzwerk, liegt auf einem fremden Server und wird von Software verarbeitet, die Sie nicht selbst betreiben. Bei Architektur B läuft dieselbe Validierungslogik in Ihrem Browser – mittels WebAssembly, kompiliert aus demselben C++-Code, der auch native Desktop-BIM-Tools antreibt. Nichts verlässt das Gerät, und es ist kein Dritter an der Verarbeitung beteiligt.",
