        type: "p",
        text: "Der Reflex, IFC-Dateien wie PDFs zu behandeln – teilbar, hochladbar, überall archivierbar – unterschätzt, was in einem komplexen Gebäudemodell steckt. Eine IFC-Datei ist eine strukturierte Datenbank mit Objektinformationen. Bei vielen Projektarten sind diese Informationen tatsächlich sensibel, zugangsbeschränkt oder als vertraulich eingestuft.",
