        text: "Über den Projekttyp hinaus enthalten IFC-Dateien Metadaten, die nach mehreren Rechtsrahmen als sensibel gelten. Das Feld FILE_NAME im STEP-Dateikopf enthält Namen von Autor und Organisation. IfcProject-Eigenschaften tragen Kunden- und Projektkennungen. Raumplanungsmodelle können Belegungszahlen und Personalverteilung enthalten. Eigenschaftssätze können Systemkapazitäten, Baukonstruktionsdaten und Betriebsmerkmale eines Gebäudes offenlegen – genau die Art von Informationen, die Industriespionage lohnend macht.",
