        variant: "warning",
        text: "Wer eine IFC-Datei mit personenbezogenen Daten ohne unterzeichneten Auftragsverarbeitungsvertrag (AVV) und ohne gültige Rechtsgrundlage nach Artikel 6 DSGVO auf einen kommerziellen Cloud-Dienst hochlädt, verstößt gegen die Vorschriften – unabhängig davon, ob der Dienst die Daten bei der Übertragung verschlüsselt. Nach Artikel 28 DSGVO benötigt jeder Auftragsverarbeiter, der personenbezogene Daten im Auftrag eines Verantwortlichen verarbeitet, einen formalen AVV. „Der Dienst nutzt HTTPS“ ersetzt keinen AVV.",
