        text: "Eine 250-MB-IFC-Datei, die von Grund auf neu geparst wird, braucht auf einem aktuellen Rechner 20–40 Sekunden. Dieselbe Datei aus dem OPFS-Cache lädt in 2–3 Sekunden. Für einen BIM-Koordinator, der dasselbe Projektmodell mehrmals täglich öffnet, macht OPFS den Unterschied zwischen einem Tool, das sich schnell anfühlt, und einem, bei dem man wartet. Und weil der OPFS-Speicher pro Ursprung isoliert ist und im lokalen Dateisystem liegt, erreichen die zwischengespeicherten Modelldaten nie einen Server – sie genießen dieselbe Datenschutzgarantie wie die Browser-Validierung selbst.",
