        type: "p",
        text: "IFC Viewer Online ist eine browserbasierte Umsetzung von Architektur B. Der IFC-Parser (web-ifc, zu WASM kompiliert), die Validierungs-Engine mit 44 Regeln, die Berechnung des Health Score, die IDS-1.0-Prüf-Engine, das BCF-Panel und der 3D-Renderer (Three.js über WebGL) laufen alle im Browser. Nichts wird hochgeladen. Die Architektur erzwingt das auf Implementierungsebene – es gibt keinen serverseitigen Endpunkt, an den Modelldaten gesendet werden könnten.",
