        text: "Ja, sofern korrekt implementiert. WebAssembly läuft in einer isolierten Browser-Sandbox. Das File-Objekt mit den IFC-Daten wird im lokalen Browser-Speicher erzeugt. Damit diese Daten einen Server erreichen, müsste der Code ausdrücklich eine Netzwerk-API aufrufen. Ein korrekt implementierter Browser-Validator tut das für die IFC-Datei nicht. Prüfen Sie das selbst: Öffnen Sie den Netzwerk-Tab der Entwicklertools (F12 → Netzwerk) und bestätigen Sie, dass beim Öffnen und Validieren eines Modells kein Upload stattfindet.",
