            "Vollständige IDS-1.0-Unterstützung: alle sechs Facetten, validiert gegen 100 offizielle bSI-Testfälle",
            "Zerstörungsfreie Eigenschaftsbearbeitung, GUID-Reparatur und Pset-Korrektur mit vollständigem Rückgängig machen",
