        type: "p",
        text: "Am besten für: BIM-Koordinatoren, die eine schnelle, private QS vor der Lieferung brauchen; Berater, die IFC-Dateien aus mehreren Quellen erhalten und nicht auf Server Dritter hochladen dürfen; Teams, die IDS-basierte Lieferanforderungen umsetzen. Kostenlos, kein Konto erforderlich.",
