        text: "Trimble Connect ist eher eine cloudbasierte BIM-Kollaborationsplattform als ein reiner IFC-Viewer. Sie umfasst einen Web-Viewer, einen Desktop-Client und eine mobile App. Teams laden Modelle in die Trimble-Cloud-Infrastruktur hoch, wo sie angesehen, mit anderen Modellen föderiert und mit BCF-Themen für die fachübergreifende Koordination verknüpft werden können. Die kostenlose Stufe umfasst 5 GB Projektspeicher – ausreichend für kleine Projekte oder die Durchsicht einzelner Modelle.",
