        text: "Dalux ist eine dänische Plattform für BIM- und Dokumentenmanagement, die in Skandinavien und Nordeuropa weit verbreitet ist. Ihr stärkstes Unterscheidungsmerkmal ist die mobil-first ausgelegte IFC-Ansicht – die iOS- und Android-Apps sind eigens für die Begehung vor Ort entwickelt, mit BCF-Themenerstellung direkt vom Smartphone oder Tablet aus. Für Generalunternehmer und Nachunternehmer, die vor Ort koordinieren, ist Dalux das leistungsfähigste kostenlose IFC-Tool, das es gibt.",
