        text: "Dalux ist für Auftragnehmer kostenlos, was die Verbreitung in der Lieferkette stark vorangetrieben hat. Die Plattform für Generalunternehmer (Dalux Box) ist ein Enterprise-Abo, aber Nachunternehmer, die darüber geteilte Modelle nutzen, erhalten kostenlosen Zugang. Durch dieses asymmetrische Preismodell nutzen viele Teams vor Ort Dalux ohne eigene Budgetposition. Außerhalb Skandinaviens ist Dalux weniger verbreitet – wird aber in Europa zunehmend eingesetzt.",
