        text: "Jedes Tool in diesem Leitfaden, das einen Cloud-Upload erfordert – Autodesk Viewer, Trimble Connect, Dalux, buildingSMART Validation Service – speichert Ihre IFC-Datei auf einem Server eines Drittanbieters. Für die meisten kommerziellen Bauprojekte ist das ein akzeptabler Kompromiss. Bei Behördeninfrastruktur, Verteidigungsanlagen, Gesundheitsgebäuden oder jedem Projekt mit Anforderungen an die Datenhoheit oder die DSGVO kann das anders sein. Prüfen Sie vor der Wahl eines cloudbasierten Tools für sensible Projekte den Auftragsverarbeitungsvertrag (AVV) des Anbieters, die Optionen zum Datenstandort und die Aufbewahrungsrichtlinien. Artikel 28 DSGVO verlangt einen unterzeichneten AVV für jeden Auftragsverarbeiter, der personenbezogene Daten verarbeitet – dazu können Namen von Gebäudeeigentümern und Koordinaten zählen, die in IFC-Eigenschaftssätzen eingebettet sind.",
