        text: "Standardmäßige IFC-Eigenschaftssätze (Psets) wie Pset_WallCommon, Pset_BeamCommon und Pset_SpaceCommon enthalten die Daten, auf die nachgelagerte Tools – Mengenermittlung, FM-Übergabe, Energieanalyse – angewiesen sind. Fehlt ein Pset oder sind seine Eigenschaften leer, liefern diese nachgelagerten Prozesse falsche oder unvollständige Ergebnisse.",
