            "Ursache: Pset-Zuordnung des Exporters für diesen Elementtyp nicht konfiguriert",
            "Ursache: benutzerdefinierte Elementtypen ohne IFC-Pset-Äquivalent",
            "Ursache: Exportprofil zur Dateigrößenreduzierung auf „nur Geometrie“ gesetzt",
