            "L3-IDS-Prüfung: spezifische Anforderungen an Klassifizierungscodes nicht erfüllt",
            "Ursache: Klassifizierung im Export der Autorensoftware nicht konfiguriert",
            "Ursache: Klassifizierungssystem im Modell entspricht nicht der AIA-Anforderung",
            "Ursache: benutzerdefinierte Familien ohne Parameter für Klassifizierungscodes",
