            "Ursache: fehlerhaft ausgebildete Vorhangfassadenpaneele in Revit",
            "Ursache: komplexe Boolesche Operationen in ArchiCAD, die beim Export fehlschlagen",
            "Ursache: importierte Geometrie (aus DXF oder STEP), die nie über eine gültige Volumengeometrie verfügte",
