        type: "p",
        text: "IFC codiert Beziehungen zwischen Elementen über Beziehungsentitäten: IfcRelDefinesByType (Typ-Instanz), IfcRelAssociatesMaterial (Materialzuweisung), IfcRelConnectsElements (konstruktive Verbindungen) und weitere. Sind diese Beziehungen fehlerhaft – verweisen sie auf nicht existierende Entitäten oder auf den falschen Objekttyp –, wird das Datenmodell inkonsistent, und nachgelagerte Tools melden entweder einen Fehler oder ignorieren die betroffenen Elemente stillschweigend.",
